 const config={count:Number(process.env.VS_TEST_STAGE_COUNT||1000),concurrency:Number(process.env.VS_TEST_CONCURRENCY||1),runtimeSha:process.env.VS_TEST_EXPECT_RUNTIME_SHA,maxRequests:Number(process.env.VS_TEST_MAX_REQUESTS),maxStatusReads:Number(process.env.VS_TEST_MAX_STATUS_READS),deadlineMs:Number(process.env.VS_TEST_DEADLINE_MS)};
 const report={scope:'real isolated provider attendance; status completion is not Sheets readback',schoolId:TEST_SCHOOL,config,status:'BLOCKED',pass:false,realCloudReadbackVerified:false,operations:[],attempts:[],requests:0,statusReads:0,failures:0,failedAttemptDurationsMs:[],resourceSamples:[],startedAt:Date.now()};
